// Two levels: destination navigation, then content categories on Discover.
const discoveryRoot=document.querySelector('#discover'),categoryBar=document.querySelector('#categories');
const discoveryCategories=[['All','For You'],['Gaming','Gaming'],['Science & Technology','Science'],['Simulation','Simulation'],['Creative','Creative'],['Fun & Social','Fun'],['Knowledge','Knowledge']];
categoryBar.innerHTML=discoveryCategories.map(([value,label])=>`<button data-cat="${value}" class="${selected===value?'selected':''}" aria-pressed="${selected===value}">${label}</button>`).join('');discoveryRoot.prepend(categoryBar);
const philosophySection=document.createElement('section');philosophySection.className='product-philosophy';philosophySection.setAttribute('aria-label','思来的理念');philosophySection.append(document.querySelector('.intro'),document.querySelector('.editor-note'));document.querySelector('.app-downloads').before(philosophySection);
categoryBar.addEventListener('click',e=>{if(!e.target.matches('[data-cat]'))return;const all=selected==='All',label=discoveryCategories.find(([value])=>value===selected)?.[1]||selected;document.querySelector('.feature').hidden=!all;document.querySelector('.queue-entry').hidden=!all;document.querySelector('.browse .section-heading h2').textContent=all?'跟着好奇心走':'探索 '+label;document.querySelector('.browse .view-label').textContent=all?'▦ MAGAZINE VIEW':label.toUpperCase()+' SLICES';});

philosophySection.querySelector(".intro p")?.remove();philosophySection.querySelector(".intro .eyebrow")?.remove();philosophySection.querySelectorAll(".editor-note>span,.editor-note>p").forEach(el=>el.remove());
const featuredRow=document.createElement('div');featuredRow.className='featured-row';const featuredBlock=document.querySelector('.feature');featuredBlock.before(featuredRow);featuredRow.append(featuredBlock,document.querySelector('#trending'));document.querySelector('#trending .aside-bottom')?.remove();categoryBar.addEventListener('click',()=>{featuredRow.hidden=selected!=='All'});
